import{_ as l,l as i,o as e,c as n,v as t,p as E,x as r,d as s,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"先进过程控制 APC","description":"","frontmatter":{"title":"先进过程控制 APC","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/apc.md","filePath":"litho/apc.md","lastUpdated":1789023840000}'),A={name:"litho/apc.md"};function C(P,a,c,h,_,B){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="先进过程控制-apc" tabindex="-1">先进过程控制 APC <a class="header-anchor" href="#先进过程控制-apc" aria-label="Permalink to &quot;先进过程控制 APC&quot;">​</a></h1><div class="epigraph"><p>规格内不等于受控：APC 用模型把计量残差变成下一片的剂量、焦点或网格修正，而不是等人看见趋势再拧旋钮。</p><footer>—— 对照 SEMI 对 APC / run-to-run 的通称；IEEE 半导体生产中的先进过程控制传统</footer></div><p><a href="/litho/critical-layer-alignment">上一课</a>把对准树交到量产。缺口是闭环：读数如何变成下一场的设定。<a href="/litho/dose-control">剂量控制</a> 已有机内环；本课钉厂级 APC（advanced process control）的位置。前馈与反馈如何拆，留给[下一课](/litho/feedforward-feedback-r2r）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>机内环（剂量传感器、调平）吃掉秒级噪声。批次间胶厚、光源老化、腔体聚合物、卡盘污染是小时到周的漂移，要靠离线或近线计量 + 控制器。APC 把 CD、套刻、厚度映射到可执行的补偿：剂量偏置、焦点偏置、叠对校正项。没有模型，补偿会把噪声写进下一片。</p><p>缺口是<strong>控制层</strong>，不是再讲扫描机内部传感器。把 APC 当「自动 SPC」，会只报警不动作；把 APC 当无限权限优化器，会和 OPC 版本、食谱锁定打架。</p><h3 id="apc-不替代工艺能力" tabindex="-1">APC 不替代工艺能力 <a class="header-anchor" href="#apc-不替代工艺能力" aria-label="Permalink to &quot;APC 不替代工艺能力&quot;">​</a></h3><p>控制器不能把 \\(C_{pk}\\) 从无能变成有能。窗口本身不够时，APC 只是把均值钉在悬崖边。PWQ 与 LRC 仍是能力门；APC 管的是受控。</p><p><span class="marginnote">SEMI E133 一类标准谈的是数据与接口，不是某家算法商标。控制器要有权限、限幅和失效安全：计量坏了应停补，而不是猛拧。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>结构：计量 → 状态估计（滤波）→ 模型反演 → 限幅 → 写回扫描机/轨道/刻蚀。对象分层：CD 对剂量/焦点；套刻对网格；厚度对涂胶或 CMP。与 OPC 回环课分工：APC 动低维设定；核形状仍走工程版本。权限：哪些层开 APC、最大步长、与重工的优先级。</p><p>开环层（窗口已贴悬崖、或计量不可靠）应明确关闭 APC，只留 SPC。把所有层默认打开，会在新胶导入期把噪声写进剂量历史。SEMI 对 APC 的接口强调限幅与质量位，本课把它们当成开环开关。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>假设计量 = 真值 + 噪声，过程 = 缓变状态 + 突发。控制器常用 EWMA 一类更新状态，再按增益反推设定。增益过大振荡，过小跟不上。突发（换版、保养）应重置状态，而不是被 EWMA 慢慢吞。这与后课 SPC 的「异常规则」衔接：APC 负责补偿，SPC 负责宣布「不可再补」。</p>',14)),(e(),E(d,null,{default:r(()=>[p(o,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20MET%5B%22CD%20%2F%20%E5%A5%97%E5%88%BB%20%2F%20%E5%8E%9A%E5%BA%A6%22%5D%20--%3E%20EST%5B%22%E7%8A%B6%E6%80%81%E4%BC%B0%E8%AE%A1%22%5D%0A%20%20EST%20--%3E%20INV%5B%22%E6%A8%A1%E5%9E%8B%E5%8F%8D%E6%BC%94%20%2B%20%E9%99%90%E5%B9%85%22%5D%0A%20%20INV%20--%3E%20SET%5B%22%E6%89%AB%E6%8F%8F%E6%9C%BA%20%2F%20%E8%BD%A8%E9%81%93%20%2F%20%E5%88%BB%E8%9A%80%E8%AE%BE%E5%AE%9A%22%5D%0A%20%20SET%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E7%89%87%20%2F%20%E4%B8%8B%E4%B8%80%E6%89%B9%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>限幅后的设定不再跟踪，状态应升格给 SPC。控制器只钉均值；窗口本身仍由 PWQ 与 LRC 守门。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>APC 不修随机光子缺陷，也不改设计规则。不把未公开的控制器增益当文献。本课不写限价簿。</p><p>后课默认：厂级有限幅的设定更新。下一课把前馈（已知扰动）和反馈（残差）拆开，并落到 run-to-run。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>APC 用计量与模型更新低维设定，限幅并失效安全。</li><li>它钉均值，不创造工艺窗口。</li><li>与 OPC 核版本分层，禁止每片重 OPC。</li><li>开环层应显式关闭 APC，只留 SPC。</li><li>出处：SEMI APC/R2R 通称；半导体 APC 的 IEEE 传统。</li></ul>',6))])}const f=l(A,[["render",C]]);export{m as __pageData,f as default};
